function splitEmailQuote(value){const text=String(value||'').replace(/\r\n?/g,'\n'),lines=text.split('\n');let at=-1;
 for(let i=1;i<lines.length;i++){const sample=lines.slice(i,i+4).join(' ');if(/^(?:On\s.+\bwrote\s*:|Le\s.+\ba écrit\s*:|Am\s.+\bschrieb\b|El\s.+\bescribió\s*:|在.+写道\s*[:：])/i.test(sample.trim())&&lines.slice(i,i+7).some(l=>/^\s*>/.test(l))){at=i;break;}
 if(/^\s*-{2,}\s*(?:Original Message|原始邮件)\s*-{2,}/i.test(lines[i])){at=i;break;}
 if(/^\s*(?:From|发件人)\s*[:：]/i.test(lines[i])&&/(?:Sent|发送时间|Date)\s*[:：]/i.test(sample)&&/(?:To|收件人|Subject|主题)\s*[:：]/i.test(lines.slice(i,i+8).join(' '))){at=i;break;}}
 if(at<0){const first=lines.findIndex(l=>/^\s*>/.test(l));if(first>0&&lines.slice(first).every(l=>!l.trim()||/^\s*>/.test(l)))at=first;}
 if(at<0||!lines.slice(0,at).join('').trim())return{body:text,quote:''};return{body:lines.slice(0,at).join('\n'),quote:lines.slice(at).join('\n')};}
function emailParagraphs(value){let text=String(value||'').replace(/\r\n?/g,'\n').replace(/[\t ]+$/gm,'').replace(/\n[\t ]*\n(?:[\t ]*\n)+/g,'\n\n').trim();
 text=text.replace(/^[\t ]*([-•])[\t ]*\n(?:[\t ]*\n)*[\t ]*(?=\S)/gm,'$1 ');
 return text.split(/\n\s*\n/).filter(Boolean).map(block=>{const lines=block.split('\n'),flow=[];for(const line of lines){const prev=flow.at(-1)||'';if(prev.length>=45&&/[A-Za-z]/.test(prev)&&/^[A-Za-z*]/.test(line)&&!/^\s*(?:[-•]|\d+[.)])\s/.test(prev)&&!/^https?:\/\//i.test(prev))flow[flow.length-1]+=' '+line;else flow.push(line);}
 if(flow.every(l=>/^\s*[-•]\s+/.test(l)))return '<ul>'+flow.map(l=>'<li>'+esc(l.replace(/^\s*[-•]\s+/,''))+'</li>').join('')+'</ul>';
 return '<p>'+flow.map(esc).join('<br>')+'</p>';}).join('');}
function emailBody(value){const parts=splitEmailQuote(value);return '<div class="email-body" dir="auto">'+(emailParagraphs(parts.body)||'<p class="email-empty">此邮件无文字正文，请查看附件。</p>')+'</div>'+(parts.quote?'<details class="email-quote"><summary>查看引用的历史邮件</summary><div class="email-quote-body" dir="auto">'+esc(parts.quote.trim().replace(/\n[\t ]*\n(?:[\t ]*\n)+/g,'\n\n'))+'</div></details>':'');}
function threadEntries(d){const sent=new Set(d.outgoing.filter(m=>m.status==='accepted'&&m.from_address).map(m=>'<'+m.id+'@'+m.from_address.split('@')[1]+'>'));const seen=new Set();return [...d.messages.filter(m=>!(m.direction==='outbound'&&sent.has(m.rfc_message_id))).map(m=>({...m,entry:'message',at:m.sent_at})),...d.outgoing.map(m=>({...m,entry:'outgoing',at:m.created_at,direction:'outbound',body_text:m.body}))].sort((a,b)=>a.at.localeCompare(b.at)).filter(m=>{const key=m.rfc_message_id?m.direction+'|'+m.rfc_message_id:m.id;if(seen.has(key))return false;seen.add(key);return true;});}

function renderThread(preserve=false){const d=state.detail,thread=$('#thread'),scroll=thread.scrollTop;const expanded=new Set(Array.from(thread.querySelectorAll('details[open]')).map(n=>n.closest('[data-message-id]')?.dataset.messageId));const unique=threadEntries(d);let day='',subject='';thread.innerHTML=unique.map(m=>{
 const date=new Date(m.at).toLocaleDateString('zh-CN'),dateHtml=date!==day?'<div class="date-separator"><span>'+esc(date)+'</span></div>':'';day=date;
 const out=m.direction==='outbound',name=out?(m.actor_name||'客服'):(d.customer.display_name||d.customer.email),translation=state.translations.get(m.id);
 const topic=String(m.subject||'（无标题）').replace(/^(?:(?:re|fw|fwd|回复|答复)\s*[:：]\s*)+/i,'').trim(),showSubject=topic!==subject;subject=topic;
 return dateHtml+'<article class="message-row '+(out?'outbound':'inbound')+'" data-message-id="'+esc(m.id)+'">'+avatar(name,out?'agent':'')+'<div class="message-content"><div class="message-meta"><span class="message-role">'+(out?'客服回复':'客户来信')+'</span><span class="message-author" title="'+esc(m.from_address||name)+'">'+esc(name)+'</span><time datetime="'+esc(m.at)+'" title="'+esc(new Date(m.at).toLocaleString('zh-CN'))+'">'+esc(timeText(m.at))+'</time></div><div class="message-bubble">'+(showSubject?'<div class="message-subject">'+esc(topic)+'</div>':'')+emailBody(m.body_text)+((m.attachments||[]).length?'<div class="message-attachments" aria-label="邮件附件">'+m.attachments.map(a=>'<button class="message-attachment" data-attachment="'+esc(a.id)+'" data-outgoing="'+(a.outgoing?'true':'false')+'" data-filename="'+esc(a.filename)+'">'+icon('paperclip')+'<span>'+esc(a.filename)+'</span><small>'+Math.ceil(a.size_bytes/1024)+' KB</small></button>').join('')+'</div>':'')+'</div><div class="message-actions"><button data-copy-message="'+esc(m.id)+'">'+icon('copy')+'复制原文</button>'+(m.entry==='message'?'<button data-translate="'+esc(m.id)+'">'+icon('translate')+(translation?'收起译文':'翻译')+'</button>':'')+(out?'<span class="delivery-state">'+(m.status==='demo'?'仅本机 · 演示回复':m.status==='accepted'?'邮件服务器已接收':m.status==='failed'?'发送失败':m.status==='unknown'?'结果未知，请核对':m.status==='sending'?'发送中…':'历史记录')+'</span>':'')+'</div>'+(translation?'<div class="translation"><strong>中文译文</strong>'+emailBody(translation)+'</div>':'')+'</div></article>';
 }).join('');if(preserve){thread.querySelectorAll('details').forEach(n=>{if(expanded.has(n.closest('[data-message-id]')?.dataset.messageId))n.open=true});thread.scrollTop=scroll;}else thread.scrollTop=thread.scrollHeight;
$$('[data-copy-message]').forEach(b=>b.onclick=run(()=>copy(unique.find(m=>m.id===b.dataset.copyMessage).body_text)));$$('[data-translate]').forEach(b=>b.onclick=run(async()=>{const id=b.dataset.translate;if(state.translations.has(id)){state.translations.delete(id);renderThread(true);return;}b.disabled=true;b.textContent='翻译中…';try{const result=await api('desk/translate',{messageId:id});state.translations.set(id,result.text);renderThread();}finally{b.disabled=false;if(b.isConnected)b.textContent='翻译';}}));$$('[data-attachment]').forEach(b=>b.onclick=run(()=>previewAttachment(b)));}
let assistantPoll;
async function loadAssistant(useAI,poll=false){const id=state.id;const node=$('#assistant-slot');if(!node)return;node.setAttribute('aria-busy','true');try{const result=await api('desk/assistant',{customerId:id,useAI,poll,messageId:state.assistant?.messageId});if(state.id===id){state.assistant=poll?{...state.assistant,...result}:result;renderAssistant();}}finally{node.removeAttribute('aria-busy');}}
function renderAssistant(){clearTimeout(assistantPoll);const slot=$('#assistant-slot');if(!slot)return;const a=state.assistant;if(!lastInbound()){slot.innerHTML='';return;}slot.innerHTML=`<div class="assistant"><div class="section-head"><h2>${icon('spark')}${a?.mode==='ai'?'AI 智能助手':'客服回复助手'} <small>${a?.mode==='ai'?'AI 草稿 · 人工确认':'AI 回复预生成'}</small></h2><div class="assistant-controls"><button id="refresh-assistant" title="重新分析" aria-label="重新分析">${icon('refresh')}</button>${state.meta.aiConfigured&&!state.meta.demo?'<button id="ai-generate">重新生成</button>':''}<button id="toggle-assistant" aria-label="${state.assistantOpen?'收起':'展开'}回复助手">${icon(state.assistantOpen?'close':'plus')}</button></div></div>${state.assistantOpen?`<div class="assistant-body"><div class="assistant-cell"><h3>${icon('paperclip')}问题分析</h3><div class="analysis-lines"><p>${icon('spark')}<span>客户问题：<strong>${esc(a?.issue||'正在分析…')}</strong></span></p><p>${icon('spark')}<span>物流状态：<strong>${esc(a?.logistics||'正在读取…')}</strong></span></p><p>${icon('spark')}<span>处理建议：<strong>${esc(a?.recommendation||'请核实订单信息')}</strong></span></p></div></div><div class="assistant-cell"><h3>${icon('book')}推荐回复</h3><div class="suggested-text">${esc(a?.text||(a?.replyStatus==='failed'?'生成失败，请点击重新生成重试。':a?.replyStatus==='manual'?'点击重新生成，AI 仅使用你有权限查看的邮件。':a?.replyStatus==='disabled'?'请在设置中启用 AI 回复。':'AI 正在后台生成回复，完成后会自动显示。'))}</div><div class="insert-row"><button class="primary" id="insert-suggestion" ${a?.text?'':'disabled'}>一键插入</button></div></div></div>`:''}</div>`;$('#toggle-assistant').onclick=()=>{state.assistantOpen=!state.assistantOpen;renderAssistant();};$('#refresh-assistant').onclick=run(()=>loadAssistant(false));if($('#ai-generate'))$('#ai-generate').onclick=run(()=>loadAssistant(true));if($('#insert-suggestion'))$('#insert-suggestion').onclick=()=>{if(state.assistant?.text)insertText(state.assistant.text);};if(a&&['pending','running','retry'].includes(a.replyStatus)){const id=state.id;assistantPoll=setTimeout(()=>{if(state.id===id)loadAssistant(false,true).catch(()=>{});},5000);}}
async function updateRoute(selected){const d=state.detail,m=lastInbound();if(!m||!$('#reply-inbox'))return;if(d.ordersLoading||d.ordersError){$('#send').disabled=true;$('#route-hint').textContent=d.ordersLoading?'正在核实订单…':'订单查询失败，请重试';return;}const o=order(),shops=new Set(d.orders.map(x=>x.shop_id));const shop=o?.shop_id||(shops.size===1?[...shops][0]:null);const contacted=new Map();for(const x of d.messages.filter(x=>x.direction==='inbound')){if(!contacted.has(x.inbox_id)||x.sent_at>contacted.get(x.inbox_id))contacted.set(x.inbox_id,x.sent_at);}const choices=state.meta.accounts.inboxes.filter(i=>contacted.has(i.id)).sort((a,b)=>contacted.get(b.id).localeCompare(contacted.get(a.id))||a.id.localeCompare(b.id));const matched=shop?choices.filter(i=>i.shopIds.includes(shop)):[];const preferred=choices.length===1?choices:matched.length?matched:choices;const el=$('#reply-inbox');const previous=selected;el.innerHTML='<option value="">选择发件邮箱</option>'+choices.map(i=>`<option value="${i.id}">${esc(i.address)}</option>`).join('');el.value=choices.some(i=>i.id===previous)?previous:(preferred[0]?.id||'');const id=state.id;$('#send').disabled=true;try{const route=await api('reply-route',{messageId:m.id,orderId:state.orderId||undefined,inboxId:el.value||undefined});if(state.id!==id||!el.isConnected)return;$('#route-hint').textContent=state.meta.demo?'仅本机演示':route.smtpConfigured?'人工确认后发送':'尚未配置 SMTP';$('#send').disabled=state.sending||(!state.meta.demo&&!route.smtpConfigured);}catch(e){if(state.id===id&&el.isConnected)$('#route-hint').textContent=errorText(e);}}
function insertText(text){if(state.sending)return toast('正在保存回复，请稍候。');const area=$('#reply');if(!area){toast('请先选择一封来信。');return;}const start=area.selectionStart,end=area.selectionEnd;const prefix=area.value?area.value.slice(0,start):'';const suffix=area.value.slice(end);area.value=prefix+text+suffix;area.dispatchEvent(new Event('input'));area.focus();area.selectionStart=area.selectionEnd=start+text.length;}
async function saveDraft(manualSave=false){clearTimeout(saveTimer);if(!state.detail||!state.dirty)return state.saveQueue;const id=state.id,d=state.detail,text=state.draft,version=state.draftVersion;state.dirty=false;const task=async()=>{try{d.work=await api('customers/'+id,{revision:d.work.revision,patch:{draft:text},manualSave:manualSave===true});drafts.set(id,text);if(state.id===id&&state.draftVersion===version&&$('#draft-status'))$('#draft-status').textContent='草稿已保存';}catch(e){if(state.id===id){state.dirty=true;if($('#draft-status')){$('#draft-status').hidden=false;$('#draft-status').textContent='保存失败 · 请重试';}}throw e;}};state.saveQueue=state.saveQueue.catch(()=>{}).then(task);return state.saveQueue;}
async function addFiles(files){const total=[...state.files,...files];if(total.length>10||total.some(f=>f.size>10*1024*1024)||total.reduce((n,f)=>n+f.size,0)>15*1024*1024)throw Error('FILE_TOO_LARGE');state.files=total;state.requestId=null;renderFiles();$('#file-input').value='';}
function renderFiles(){if(!$('#files'))return;$('#files').innerHTML=state.files.map((f,i)=>`<span class="file-chip">${icon('paperclip')}${esc(f.name)} · ${Math.ceil(f.size/1024)} KB<button data-remove-file="${i}" aria-label="移除 ${esc(f.name)}">${icon('close')}</button></span>`).join('');$$('[data-remove-file]').forEach(b=>b.onclick=()=>{state.files.splice(Number(b.dataset.removeFile),1);state.requestId=null;renderFiles();});}
function updateRepliedRow(id,status){const row=state.list?.rows.find(r=>r.id===id);if(!row)return;row.status=status;if(status==='done')row.unreplied=0;const button=$$('[data-customer]').find(b=>b.dataset.customer===id);const tag=button?.querySelector('.tags .tag');if(tag){tag.className='tag '+(row.status==='done'?'green':row.unreplied?'red':'orange');tag.textContent=row.status==='done'?'已处理':row.unreplied?'未回复':'待处理';}}
async function sendReply(){if(state.sending||$('#send')?.disabled)return;if(!replyBody().trim()&&!state.files.length)return toast('请先输入回复内容或添加附件。');const id=state.id;await saveDraft();const message=lastInbound();state.sending=true;$$('.workspace button,.workspace select,.workspace textarea').forEach(el=>el.disabled=true);$('#send').textContent=state.meta.demo?'正在保存…':'正在发送…';try{const attachments=await Promise.all(state.files.map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(Error('附件读取失败'));r.onload=()=>resolve({name:f.name,data:String(r.result).split(',')[1]});r.readAsDataURL(f);})));state.requestId ||= requestUUID();const result=await api(state.meta.demo?'desk/send-demo':'send',{requestId:state.requestId,messageId:message.id,text:state.draft,orderId:state.orderId||undefined,inboxId:$('#reply-inbox').value||undefined,attachments});if(['demo','accepted'].includes(result.status)){state.dirty=false;state.draft='';drafts.delete(id);state.requestId=null;++state.listSeq;$('#list-body').removeAttribute('aria-busy');await selectCustomer(id,true,true);toast(result.status==='demo'?'演示回复已保存到本机，没有对外发送。':'邮件服务器已接收回复，实际送达需核对邮箱。');}else toast(result.status==='unknown'?'发送结果未知，请先核对已发送邮件；重复点击不会重新发信。':'发送失败，草稿已保留，请检查邮箱配置。');}finally{state.sending=false;if(state.id===id&&$('#send')){renderWorkspace();}}}
function refundEstimate(total,percent){if(!/^\d+(?:\.\d{1,2})?$/.test(String(total??''))||!/^\d+(?:\.\d{1,2})?$/.test(String(percent)))return null;const p=Number(percent);if(p<0||p>100)return null;const units=v=>{const [a,b='']=String(v).split('.');return BigInt(a)*100n+BigInt(b.padEnd(2,'0'));};const cents=(units(total)*(10000n-units(percent))+5000n)/10000n;return String(cents/100n)+'.'+String(cents%100n).padStart(2,'0');}
function orderCandidateCard(d){const candidates=d.orderCandidates||[];if(!candidates.length)return '';return '<section class="detail-card"><h2>待确认订单</h2><p class="help">未自动关联，请核对订单和店铺后选择。</p><div style="display:grid;gap:8px;max-height:220px;overflow:auto">'+candidates.map(c=>'<div><strong>'+esc(c.order_number)+'</strong><p class="help">'+esc(c.shop_name)+' · '+esc(c.reason)+(c.shopMismatch?' · 与收件邮箱店铺不一致':'')+'</p><button class="soft" data-confirm-order="'+esc(c.id)+'" aria-label="确认关联订单 '+esc(c.order_number)+'">确认关联</button></div>').join('')+'</div></section>';}
function renderDetails(){stopTrackingObservers();const d=state.detail;if(!d)return;const o=order();$('.details-panel').innerHTML=`<div class="detail-tabs"><button class="${state.detailTab==='order'?'active':''}" id="tab-order">${icon('box')}订单信息</button><button class="${state.detailTab==='tracking'?'active':''}" id="tab-tracking">物流信息</button><button class="icon-btn" id="close-details" style="margin-left:auto" aria-label="关闭详情">${icon('close')}</button></div>${orderCandidateCard(d)}${d.orders.length>1?`<select class="wide-order-select" id="detail-order" aria-label="查看关联订单">${!o?'<option value="">请选择订单</option>':''}${d.orders.map(x=>`<option value="${x.id}" ${x.id===o?.id?'selected':''}>${esc(x.order_number)} · ${esc(x.shop_name)}</option>`).join('')}</select>`:''}${!o?`<div class="no-data">${icon('box')}<h2>${d.ordersLoading?'正在查询订单…':d.ordersError?'订单查询暂时失败':d.orderCandidates?.length?'请确认本次来信的订单':'还没有关联订单'}</h2><p>${d.ordersLoading?'邮件已加载，可先阅读和编辑草稿。':d.ordersError?'请稍后重新打开会话重试，邮件不受影响。':'可按订单号搜索并手动关联。'}</p><button class="soft" id="link-order">关联订单</button></div>`:state.detailTab==='tracking'?trackingCard(o,true):`<section class="detail-card"><dl class="order-fields"><dt>订单号</dt><dd><strong>${esc(o.order_number)}</strong><button id="copy-order" aria-label="复制订单号">${icon('copy')}</button></dd><dt>订单 ID</dt><dd><span>${esc(o.provider_id||'待核实')}</span>${o.provider_id?`<button id="copy-order-id" aria-label="复制订单 ID">${icon('copy')}</button>`:''}</dd><dt>订单状态</dt><dd>${statusTag(o)}</dd><dt>下单时间</dt><dd>${esc(fullTime(o.placed_at))}</dd><dt>发货时间</dt><dd title="已发货记录创建时间；分批发货显示首次时间">${o.shipped_at?esc(fullTime(o.shipped_at)):'暂无记录'}</dd><dt>支付方式</dt><dd>${esc((!o.payment_method||['none','unknown','null'].includes(o.payment_method.toLowerCase()))?'支付待核实':o.payment_method)}</dd><dt>运费</dt><dd class="amount">${money(o,o.local.shipping)}</dd><dt>总金额</dt><dd class="amount total">${money(o)}</dd><dt>退款金额</dt><dd class="amount">${money(o,o.refunded_amount)}</dd><dt>测算退款</dt><dd class="refund-estimate"><label><input id="refund-percent" type="number" min="0" max="100" step="0.01" placeholder="扣除比例" aria-label="扣除百分比">%</label><output id="refund-estimate" for="refund-percent" aria-live="polite">输入比例</output><small>显示扣除该比例后的剩余金额，仅供参考</small></dd></dl><div class="order-item"><div class="product-placeholder" aria-label="暂无商品图片">${icon('box')}</div><div style="flex:1;min-width:0"><details class="product-title-details"><summary class="product-title" aria-label="展开或收起完整商品标题"><strong>${esc(o.local.product||'商品明细暂未同步')}</strong></summary><p class="product-title-full">${esc(o.local.product||'商品明细暂未同步')}</p></details><p style="margin-top:7px">${esc(o.local.variant||'规格待核实')} ${o.local.product?'/ '+o.local.quantity:''}</p><div class="item-price"><span class="amount">${money(o)}</span><button class="soft" id="edit-product">修改规格备注</button></div></div></div>${!state.meta.demo?'<p class="local-hint">商品及地址补充信息为本机备注，不会修改店铺订单。</p>':''}</section>${trackingCard(o,false)}<section class="detail-card"><h2>收货地址 <small>· 本机资料</small></h2><div class="address-row">${avatar(o.local.recipient||d.customer.display_name,'agent')}<div><strong>${esc(o.local.recipient||d.customer.display_name)}</strong><br>${esc(o.local.phone||d.profile.phone||'电话暂无')}<br>${esc(o.local.address||d.profile.address||'收货地址尚未同步')}</div></div><div class="address-actions"><button class="soft" id="copy-address">复制</button><button class="soft" id="edit-address">修改备注</button></div></section>`}`;
$('#tab-order').onclick=()=>{state.detailTab='order';renderDetails();};$('#tab-tracking').onclick=()=>{state.detailTab='tracking';renderDetails();};$('#close-details').onclick=()=>{$('.app-shell').classList.remove('show-details');setMobile('thread');};if($('#detail-order'))$('#detail-order').onchange=run(async e=>{await saveDraft();state.orderId=e.target.value;renderDetails();if($('#reply-order'))$('#reply-order').value=state.orderId;await updateRoute();});if($('#link-order'))$('#link-order').onclick=linkOrder;document.querySelectorAll('[data-confirm-order]').forEach(b=>b.onclick=run(async()=>{const customerId=state.id,id=b.dataset.confirmOrder,candidate=d.orderCandidates.find(c=>c.id===id);b.disabled=true;try{await api('order-links',{customerId,orderId:id,messageId:candidate.messageId});if(state.id!==customerId)return;await selectCustomer(customerId,true);if(state.detail.orders.some(o=>o.id===id)){state.orderId=id;renderDetails();if($('#reply-order'))$('#reply-order').value=id;await updateRoute();}}finally{if(b.isConnected)b.disabled=false;}}));if(!o)return;
if($('#copy-order-id'))$('#copy-order-id').onclick=run(()=>copy(o.provider_id));if($('#refund-percent'))$('#refund-percent').oninput=e=>{const value=refundEstimate(o.total_amount,e.target.value);$('#refund-estimate').textContent=value===null?(e.target.value?'请输入 0–100，最多两位小数':'输入比例'):money(o,value);};observeTracking();if($('#copy-virtual-progress'))$('#copy-virtual-progress').onclick=run(()=>copy(virtualProgressText(o.virtualProgress)));if($('#copy-order'))$('#copy-order').onclick=run(()=>copy(o.order_number));if($('#edit-product'))$('#edit-product').onclick=()=>editOrder('product');if($('#edit-address'))$('#edit-address').onclick=()=>editOrder('address');if($('#copy-address'))$('#copy-address').onclick=run(()=>copy([o.local.recipient||d.customer.display_name,o.local.phone||d.profile.phone,o.local.address||d.profile.address].filter(Boolean).join('\n')));if($('#view-all-tracking'))$('#view-all-tracking').onclick=()=>{state.detailTab='tracking';renderDetails();};if($('#copy-tracking'))$('#copy-tracking').onclick=run(()=>copy(o.shipments[0].tracking_number));}
let trackingScript;
function loadTrackingPlugin(){if(window.YQV5)return Promise.resolve();if(trackingScript)return trackingScript;trackingScript=new Promise((resolve,reject)=>{const script=document.createElement('script');const timer=setTimeout(()=>{script.remove();trackingScript=null;reject(Error('17TRACK 加载超时，请重试或在官网查询。'));},15000);script.src='https://www.17track.net/externalcall.js';script.async=true;script.onload=()=>{clearTimeout(timer);if(window.YQV5)resolve();else{trackingScript=null;reject(Error('17TRACK 插件暂时不可用。'));}};script.onerror=()=>{clearTimeout(timer);script.remove();trackingScript=null;reject(Error('17TRACK 加载失败，请重试或在官网查询。'));};document.head.appendChild(script);});return trackingScript;}
let trackingObserver=null;const trackingTimers=new Map();
function stopTrackingObservers(){trackingObserver?.disconnect();trackingObserver=null;for(const timer of trackingTimers.values())clearTimeout(timer);trackingTimers.clear();}
function observeTracking(){const nodes=$$('[data-inline-tracking]');if(!nodes.length)return;trackingObserver=new IntersectionObserver(entries=>{for(const entry of entries){const node=entry.target;if(!entry.isIntersecting){clearTimeout(trackingTimers.get(node));trackingTimers.delete(node);continue;}if(node.dataset.started||trackingTimers.has(node))continue;trackingTimers.set(node,setTimeout(()=>{trackingTimers.delete(node);if(!node.isConnected)return;node.dataset.started='true';loadInlineTracking(node);},350));}},{threshold:0.05});nodes.forEach(node=>trackingObserver.observe(node));}
async function loadInlineTracking(node){node.textContent='正在查询物流…';node.setAttribute('aria-busy','true');try{await loadTrackingPlugin();if(!node.isConnected)return;window.YQV5.trackSingle({YQ_ContainerId:node.id,YQ_Height:560,YQ_Fc:'0',YQ_Lang:'en',YQ_Num:node.dataset.inlineTracking});const frame=node.querySelector('iframe');if(frame){frame.title='17TRACK 物流查询结果';frame.addEventListener('load',()=>node.removeAttribute('aria-busy'),{once:true});}}catch(e){if(!node.isConnected)return;node.textContent=e.message+' ';node.removeAttribute('aria-busy');const button=document.createElement('button');button.type='button';button.className='soft';button.textContent='重试';button.onclick=()=>loadInlineTracking(node);node.appendChild(button);}}
function virtualProgressTime(at){if(!at)return 'Just now';const parts=new Intl.DateTimeFormat('en-US',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZoneName:'short'}).formatToParts(new Date(at));const m=Object.fromEntries(parts.map(p=>[p.type,p.value]));return m.year+'-'+m.month+'-'+m.day+' '+m.hour+':'+m.minute+':'+m.second+' '+m.timeZoneName;}
function virtualProgressText(progress){return ['Order Progress',progress.events.length?progress.events.map(event=>[event.label,event.desc,'Completed '+virtualProgressTime(event.at)].join('\n')).join('\n\n'):'Order processing will begin shortly.','📦 Your order is being expedited.'].join('\n\n');}
function virtualProgressCard(o,full){const progress=o.virtualProgress;if(!progress?.simulated||(o.shipments||[]).some(s=>String(s.tracking_number||'').trim()))return '';return `<section class="detail-card virtual-progress"><h2>Order Progress</h2>${progress.events.length?`<ol class="timeline">${progress.events.map(event=>`<li><span lang="en">${esc(event.label)}</span><p lang="en">${esc(event.desc)}</p><time><span class="tag green">Completed</span> ${esc(virtualProgressTime(event.at))}</time></li>`).join('')}</ol>`:'<p class="muted" lang="en">Order processing will begin shortly.</p>'}<p class="muted" lang="en">📦 Your order is being expedited.</p><div class="address-actions"><button type="button" class="soft" id="copy-virtual-progress">复制全部进度</button></div></section>`;}
function trackingCard(o,full){return `<section class="detail-card"><div class="detail-head"><h2>物流信息</h2>${full?'':`<button id="view-all-tracking">查看全部</button>`}</div>${full?`<p class="muted" style="font-size:11px">${esc(o.shipments[0]?.carrier||'暂无承运商')}</p><div class="tracking-number">${esc(o.shipments[0]?.tracking_number||'暂无运单号')}${o.shipments.length?`<button id="copy-tracking" aria-label="复制物流单号">${icon('copy')}</button>`:''}</div>`:''}${!state.meta.demo?o.shipments.filter(x=>x.tracking_number).map(x=>`<div class="inline-tracking"><p class="tracking-number">${esc(x.tracking_number)}</p><div id="tracking-${requestUUID()}" data-inline-tracking="${esc(x.tracking_number)}" style="min-height:90px"><p class="muted">进入此区域后自动查询物流…</p></div><a href="https://t.17track.net/en#nums=${encodeURIComponent(x.tracking_number)}" target="_blank" rel="noopener noreferrer">在 17TRACK 官网打开</a>${trackingCaptureView(o,x.tracking_number)}</div>`).join(''):''}${o.tracking.length?`<ol class="timeline">${o.tracking.slice(0,full?100:4).map(t=>`<li><span>${esc(t.status)}</span><time>${esc(new Date(t.at).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}))}</time><p>${esc(t.location)}</p></li>`).join('')}</ol>`:`<div class="no-data" style="padding:17px 0">${icon('truck')}${o.shipments.length?'物流由 17TRACK 自动查询。':'订单暂无物流单号。'}</div>`}<p class="local-hint">${state.meta.demo?'示例物流轨迹，用于演示页面流程。':(o.source==='postgresql'?'订单来自外部数据库快照；运单号不代表实时物流轨迹。':'实时物流请通过 17TRACK 查询。')}</p></section>${virtualProgressCard(o,full)}`;}
async function copy(text){if(!text)return toast('暂无可复制内容');try{await navigator.clipboard.writeText(text);toast('已复制');}catch{modal('复制内容',`<p class="help">浏览器未允许自动复制，请选中下方内容手动复制。</p><textarea readonly aria-label="待复制内容">${esc(text)}</textarea>`);}}
function modal(title,body){const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-btn" id="close-dialog" aria-label="关闭对话框">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();$('#close-dialog').onclick=()=>dialog.close();return dialog;}
function formModal(title,body,onSubmit){modal(title,`<form id="edit-form" style="padding:0">${body}<p class="error-copy" id="form-error" role="alert"></p><div class="form-actions"><button type="button" id="cancel-form">取消</button><button class="primary" type="submit">保存</button></div></form>`);$('#cancel-form').onclick=()=>$('#dialog').close();$('#edit-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const close=await onSubmit(new FormData(e.target));if(close!==false)$('#dialog').close();toast('已保存到本机');}catch(err){$('#form-error').textContent=errorText(err);}finally{button.disabled=false;}};}
function editProfile(){const d=state.detail,p=d.profile;formModal('顾客资料',`<p class="help">补充本机顾客资料，不会向顾客发送消息。</p><label>国家 / 地区<input name="country" maxlength="80" value="${esc(p.country||'')}"></label><label>联系电话<input name="phone" maxlength="80" value="${esc(p.phone||'')}"></label><label>地址备注<textarea name="address" maxlength="2000">${esc(p.address||'')}</textarea></label><label class="check-row"><input type="checkbox" name="vip" ${p.vip?'checked':''}>VIP 顾客</label>`,async f=>{await saveDraft();await api('desk/profile',{customerId:d.customer.id,country:f.get('country'),phone:f.get('phone'),address:f.get('address'),vip:f.has('vip')});state.detail=await api('desk/customers/'+d.customer.id);renderWorkspace();renderDetails();await loadList();});}
function editOrder(kind){const o=order(),l=o.local;formModal(kind==='product'?'修改商品规格备注':'修改收货地址备注',`<p class="help">仅保存本机备注，不会修改店铺订单或通知仓库。实际变更需到店铺核实处理。</p>${kind==='product'?`<label>商品名称<input name="product" maxlength="300" value="${esc(l.product||'')}"></label><label>规格 / 颜色 / 尺码<input name="variant" maxlength="300" value="${esc(l.variant||'')}"></label>`:`<label>收货人<input name="recipient" maxlength="300" value="${esc(l.recipient||state.detail.customer.display_name)}"></label><label>联系电话<input name="phone" maxlength="300" value="${esc(l.phone||'')}"></label><label>完整地址<textarea name="address" maxlength="2000">${esc(l.address||'')}</textarea></label>`}`,async f=>{await api('desk/order',{orderId:o.id,...Object.fromEntries(f)});Object.assign(l,Object.fromEntries(f));renderDetails();});}
function assignAgent(){const d=state.detail;formModal('分配客服',`<label>负责人<select name="staff"><option value="">未分配</option>${state.meta.staff.map(s=>`<option value="${s.id}" ${s.id===d.work.assignee_id?'selected':''}>${esc(s.display_name)}</option>`).join('')}</select></label>`,async f=>{await saveDraft();d.work=await api('customers/'+d.customer.id,{revision:d.work.revision,patch:{assigneeId:f.get('staff')||null}});await loadList();});}
function classifyMessage(){const m=lastInbound();if(!m)return toast('该顾客没有可分类的来信。');formModal('修改最新来信分类',`<label>业务分类<select name="category" id="class-category">${Object.keys(state.meta.taxonomy).map(c=>`<option ${m.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>细分分类<select name="subcategory" id="class-subcategory"></select></label>`,async f=>{await api('classify',{messageId:m.id,category:f.get('category'),subcategory:f.get('subcategory')});m.category=f.get('category');m.subcategory=f.get('subcategory');await loadList();await loadAssistant(false);});const update=()=>{$('#class-subcategory').innerHTML=state.meta.taxonomy[$('#class-category').value].map(c=>`<option ${c===m.subcategory?'selected':''}>${esc(c)}</option>`).join('');};$('#class-category').onchange=update;update();}
function customerTags(selected){if(!state.detail)return toast('请先选择顾客。');const d=state.detail;const selectedIds=Array.isArray(selected)?selected:d.labels.map(l=>l.id);formModal('顾客标签',`<div class="tag-options">${state.meta.labels.map(t=>`<label><input type="checkbox" name="labels" value="${t.id}" ${selectedIds.includes(t.id)?'checked':''}><span class="tag ${esc(t.color)}" ${labelStyle(t.color)}>${esc(t.name)}</span></label>`).join('')}</div><button type="button" class="soft" id="create-customer-label" style="margin-top:16px">${icon('plus')}创建标签</button><p class="help" style="margin-top:10px">勾选需要添加的标签，取消勾选可移除。</p>`,async f=>{const ids=f.getAll('labels');await api('customer-labels',{customerId:d.customer.id,labelIds:ids});d.labels=state.meta.labels.filter(l=>ids.includes(l.id));renderCustomerLabels();await loadList();});$('#create-customer-label').onclick=()=>{const selected=Array.from(new FormData($('#edit-form')).getAll('labels'));labelManager(id=>customerTags(id?[...selected,id]:selected));};}
function labelStyle(color){if(!/^#[0-9a-f]{6}$/i.test(color||''))return'';const channels=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);const luminance=channels[0]*.2126+channels[1]*.7152+channels[2]*.0722;return`style="background:${color};color:${luminance>.179?'#111111':'#ffffff'}"`;}
function labelManager(onCreated){const colors=['#e5e5e5','#f8b6a6','#f8d2a0','#fff575','#d7efaf','#c5e4f9','#decdef','#f4d0e5','#bfbfbf','#e97962','#efb366','#f6e35b','#b8dd7b','#91c9ed','#bc9bda','#e399c4','#858585','#cf202a','#dc8e29','#d3c244','#8cbe44','#60a7d9','#9971c1','#c2649d','#151515','#a50000','#aa5800','#a4932d','#538c24','#3579b1','#77469d','#9c2d74'];formModal('创建标签',`<label>标签名称<input name="name" maxlength="80" required placeholder="标签名称" autocomplete="off"></label><fieldset class="label-palette"><legend>标签颜色</legend><div class="label-swatches">${colors.map((color,i)=>`<label class="label-swatch" title="${color}"><input type="radio" name="color" value="${color}" aria-label="颜色 ${color}" ${i===13?'checked':''}><span ${labelStyle(color)}>${icon('check')}</span></label>`).join('')}</div></fieldset>`,async f=>{const result=await api('labels',{name:f.get('name'),color:f.get('color'),tone:'light'});await refreshMeta();renderFilters();if(typeof onCreated==='function'){$('#dialog').classList.remove('label-create-dialog');onCreated(result.id);return false;}});const dialog=$('#dialog');dialog.classList.add('label-create-dialog');dialog.addEventListener('close',()=>dialog.classList.remove('label-create-dialog'),{once:true});if(typeof onCreated==='function')$('#cancel-form').onclick=()=>{dialog.classList.remove('label-create-dialog');onCreated();};}

async function refreshMeta(){state.meta=await api('desk/meta');}
const templateVariables=[['name','顾客姓名'],['email','顾客邮箱'],['order','订单号'],['tracking_number','物流单号'],['carrier','承运商'],['tracking_url','17TRACK 查询链接'],['tracking_info','物流详情（Copy Details）'],['shop','店铺名称']];
function templateTrackingDetails(selectedOrder){
 const numbers=[...new Set((selectedOrder?.shipments||[]).map(s=>String(s.tracking_number||'').toUpperCase()).filter(Boolean))];
 const captures=numbers.map(number=>(selectedOrder?.trackingCaptures||[]).find(c=>c.number===number&&c.copy_details&&Date.now()-Date.parse(c.captured_at)<86400000));
 if(numbers.length&&captures.every(Boolean))return captures.map(c=>c.copy_details).join('\n\n');
 if(captures.some(Boolean))return '';
 return (selectedOrder?.tracking||[]).map(x=>[x.at,x.status,x.location].filter(Boolean).join(' · ')).join('\n');
}
function templateValues(detail,selectedOrder){const shipments=selectedOrder?.shipments||[];return{name:detail?.customer.display_name||'customer',email:detail?.customer.email||'',order:selectedOrder?.order_number||'',order_number:selectedOrder?.order_number||'',tracking_number:[...new Set(shipments.map(x=>x.tracking_number).filter(Boolean))].join(', '),carrier:[...new Set(shipments.map(x=>x.carrier).filter(Boolean))].join(', '),tracking_url:shipments.filter(x=>x.tracking_number).map(x=>'https://t.17track.net/en#nums='+encodeURIComponent(x.tracking_number)).join('\n'),tracking_info:templateTrackingDetails(selectedOrder),shop:selectedOrder?.shop_name||''};}
function fillTemplate(body,values){const missing=[];const text=body.replace(/\{([^{}]+)\}/g,(match,key)=>{if(!Object.hasOwn(values,key)||!values[key]){missing.push(key);return match;}return String(values[key]);});return{text,missing:[...new Set(missing)]};}
function insertTemplate(id){const t=state.meta.templates.find(t=>t.id===id);if(!t)return false;if(!lastInbound()){toast('请先选择有来信的顾客。');return false;}const result=fillTemplate(t.body,templateValues(state.detail,order()));if(result.missing.length){toast('缺少模板数据：'+result.missing.map(k=>templateVariables.find(v=>v[0]===k)?.[1]||k).join('、')+'。请核实资料或修改模板后再插入。');return false;}insertText(result.text);toast('话术已插入，可编辑后发送');return true;}

let phraseObserver,phraseEvents;
function orderedTemplates(){const rank=new Map((state.meta.templateOrder||[]).map((id,i)=>[id,i]));return [...state.meta.templates].sort((a,b)=>(rank.get(a.id)??Infinity)-(rank.get(b.id)??Infinity));}
function renderQuickPhrases(){
 phraseObserver?.disconnect();phraseEvents?.abort();phraseEvents=new AbortController();
 const bar=$('#quick-phrases');if(!bar)return;
 let dragging=null,saving=false,suppressClick=false,closeTimer;
 const templates=()=>orderedTemplates();
 const button=t=>`<button type="button" class="phrase-choice" draggable="true" data-phrase="${esc(t.id)}" title="${esc(t.title)} · 拖动排序，Alt + 左右方向键调整">${esc(t.title)}</button>`;
 bar.innerHTML=`<div class="phrase-inline">${templates().map(button).join('')}</div><button type="button" class="phrase-more" aria-expanded="false" aria-controls="phrase-drawer">更多模板</button><div id="phrase-drawer" class="phrase-drawer" popover="manual" role="region" aria-label="选择话术"><div class="phrase-drawer-head"><strong>全部话术</strong><span>拖动排序 · 仅对自己生效</span><button type="button" class="phrase-close" aria-label="关闭话术抽屉">关闭</button></div><div class="phrase-drawer-list">${templates().map(t=>`<div class="phrase-entry" draggable="true" data-phrase="${esc(t.id)}"><button type="button" class="phrase-use"><strong>${esc(t.title)}</strong><span>${esc(t.body)}</span></button></div>`).join('')||'<p>暂无话术，可在话术库新建。</p>'}</div><button type="button" class="phrase-manage">管理话术库</button></div>`;
 const inline=bar.querySelector('.phrase-inline'),more=bar.querySelector('.phrase-more'),drawer=bar.querySelector('.phrase-drawer');
 const isOpen=()=>drawer.matches(':popover-open');
 const close=()=>{clearTimeout(closeTimer);if(isOpen())drawer.hidePopover();more.setAttribute('aria-expanded','false');};
 const position=()=>{const r=bar.getBoundingClientRect();drawer.style.width=Math.min(560,window.innerWidth-24)+'px';drawer.style.maxHeight=Math.max(120,Math.min(380,r.top-16))+'px';drawer.style.left=Math.max(12,Math.min(r.right-drawer.offsetWidth,window.innerWidth-drawer.offsetWidth-12))+'px';drawer.style.top=Math.max(8,r.top-drawer.offsetHeight-4)+'px';};
 const open=()=>{clearTimeout(closeTimer);if(!isOpen())drawer.showPopover();more.setAttribute('aria-expanded','true');position();};
 const layout=()=>{const buttons=[...inline.children];buttons.forEach(b=>b.hidden=false);more.hidden=false;const widths=buttons.map(b=>b.getBoundingClientRect().width);const total=widths.reduce((a,b)=>a+b,0)+Math.max(0,widths.length-1)*4;const available=bar.clientWidth;const overflow=total>available;more.hidden=!overflow&&buttons.length>0;let used=0;const limit=available-(more.hidden?0:more.getBoundingClientRect().width+4);let full=false;buttons.forEach((b,i)=>{const next=used+(i?4:0)+widths[i];if(full||next>limit){b.hidden=true;full=true;}else used=next;});if(isOpen())position();};
 const reorder=async(from,to,after=false)=>{if(saving||from===to)return;const old=[...(state.meta.templateOrder||[])],ids=templates().map(t=>t.id);if(!ids.includes(from)||!ids.includes(to))return;ids.splice(ids.indexOf(from),1);ids.splice(ids.indexOf(to)+(after?1:0),0,from);saving=true;state.meta.templateOrder=ids;arrange();try{const result=await api('desk/template-order',{ids});state.meta.templateOrder=result.templateOrder;toast('话术排序已保存到当前账号');}catch(e){state.meta.templateOrder=old;toast('排序保存失败，已恢复原顺序：'+errorText(e));}finally{saving=false;arrange();}};
 const arrange=()=>{for(const t of templates()){for(const container of [inline,drawer.querySelector('.phrase-drawer-list')]){const item=[...container.children].find(el=>el.dataset.phrase===t.id);if(item)container.append(item);}}layout();};
 more.onpointerenter=e=>{if(e.pointerType!=='touch')open();};more.onclick=open;more.onfocus=open;
 for(const el of [more,drawer]){el.onpointerenter=()=>clearTimeout(closeTimer);el.onpointerleave=()=>{closeTimer=setTimeout(()=>{if(!drawer.contains(document.activeElement)&&!dragging)close();},250);};}
 // Opening on hover must survive the pointer crossing the small gap to the drawer.
 more.onpointerenter=e=>{clearTimeout(closeTimer);if(e.pointerType!=='touch')open();};
 drawer.querySelector('.phrase-close').onclick=()=>{close();};drawer.querySelector('.phrase-manage').onclick=()=>{close();templateLibrary();};
 bar.onclick=e=>{if(suppressClick||saving)return;const item=e.target.closest('[data-phrase]');if(item&&insertTemplate(item.dataset.phrase))close();};
 bar.ondragstart=e=>{const item=e.target.closest('[data-phrase]');if(!item||saving){e.preventDefault();return;}dragging=item.dataset.phrase;suppressClick=true;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragging);};
 bar.ondragover=e=>{if(!dragging)return;const item=e.target.closest('[data-phrase]');if(item){e.preventDefault();e.dataTransfer.dropEffect='move';bar.querySelectorAll('.phrase-drop').forEach(n=>n.classList.remove('phrase-drop'));item.classList.add('phrase-drop');}if(e.target===more)open();};
 bar.ondrop=e=>{const target=e.target.closest('[data-phrase]');if(!dragging||!target)return;e.preventDefault();const r=target.getBoundingClientRect(),after=target.classList.contains('phrase-entry')?e.clientY>r.top+r.height/2:e.clientX>r.left+r.width/2;reorder(dragging,target.dataset.phrase,after);};
 bar.ondragend=()=>{dragging=null;bar.querySelectorAll('.phrase-drop').forEach(n=>n.classList.remove('phrase-drop'));setTimeout(()=>suppressClick=false,0);};
 bar.onkeydown=e=>{if(e.key==='Escape'){close();more.focus();close();return;}const item=e.target.closest('[data-phrase]');if(item&&e.altKey&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const ids=templates().map(t=>t.id),delta=['ArrowRight','ArrowDown'].includes(e.key)?1:-1,target=ids[ids.indexOf(item.dataset.phrase)+delta];if(target)reorder(item.dataset.phrase,target,delta>0);}};
 document.addEventListener('pointerdown',e=>{if(!bar.contains(e.target))close();},{signal:phraseEvents.signal});
 window.addEventListener('resize',layout,{signal:phraseEvents.signal});phraseObserver=new ResizeObserver(layout);phraseObserver.observe(bar);layout();
}

function templateLibrary(){modal('回复话术库',`<p class="help">支持顾客、订单、物流单号、承运商、查询链接及已有轨迹变量，可在编辑时点击插入。内容取自当前选中的订单，发送前请确认。</p><button class="soft" id="new-template" style="margin-bottom:14px">${icon('plus')}新建话术</button><div class="template-list">${state.meta.templates.map(t=>`<div class="template-entry"><h3>${esc(t.title)}</h3><p>${esc(t.body)}</p><div class="actions"><button data-edit-template="${t.id}">编辑</button><button class="soft" data-use-template="${t.id}">插入回复</button></div></div>`).join('')||'<p class="help">还没有话术，先创建一条。</p>'}</div>`);$('#new-template').onclick=()=>editTemplate();$$('[data-edit-template]').forEach(b=>b.onclick=()=>editTemplate(b.dataset.editTemplate));$$('[data-use-template]').forEach(b=>b.onclick=()=>{if(!lastInbound())return toast('请先选择有来信的顾客。');if(insertTemplate(b.dataset.useTemplate))$('#dialog').close();});}
function editTemplate(id){const t=state.meta.templates.find(t=>t.id===id)||{};formModal(id?'编辑话术':'新建话术',`<label>标题<input name="title" required maxlength="100" value="${esc(t.title||'')}"></label><label>关键词<input name="keywords" required maxlength="300" value="${esc(t.keywords||'')}"></label><label>回复内容<textarea name="body" required maxlength="20000">${esc(t.body||'')}</textarea></label><div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px">${templateVariables.map(([key,label])=>`<button type="button" class="soft" data-template-variable="${key}" title="{${key}}">${label}</button>`).join('')}</div><p class="help">点击变量插入到光标位置。{tracking_info} 使用系统已保存的物流详情；右侧 17TRACK 显示不等于已保存。尚未保存时，可点击 17TRACK 的 Copy Details，将原文粘贴到回复框。</p>`,async f=>{await api('templates',{...Object.fromEntries(f),...(id?{id}:{})});await refreshMeta();if(state.detail){await saveDraft();renderWorkspace();}});$$('[data-template-variable]').forEach(b=>b.onclick=()=>{const input=$('#dialog textarea[name=body]');input.setRangeText('{'+b.dataset.templateVariable+'}',input.selectionStart,input.selectionEnd,'end');input.focus();});}
function linkOrder(){
 const d=state.detail,current=order(),messageId=lastInbound()?.id;
 modal('关联店铺订单','<label>添加方式<select id="order-search-mode"><option value="order">订单号 / 顾客邮箱</option><option value="tracking">物流单号</option></select></label><label><span id="order-search-label">搜索订单号或顾客邮箱</span><input id="order-search" placeholder="输入订单号或顾客邮箱…"></label><div id="order-results"></div>');
 const input=$('#order-search'),mode=$('#order-search-mode'),slot=$('#order-results');let timer,seq=0;
 function schedule(){clearTimeout(timer);const request=++seq,term=input.value.trim(),tracking=mode.value==='tracking';slot.innerHTML='';if(!term)return;timer=setTimeout(run(async()=>{
  const rows=await api('orders?q='+encodeURIComponent(term));if(request!==seq||!slot.isConnected)return;
  slot.innerHTML=rows.slice(0,15).map(o=>'<button class="outline" style="width:100%;margin-top:6px;justify-content:space-between" data-link="'+esc(o.id)+'"><span>'+esc(o.order_number)+' · '+esc(o.shop_name)+(tracking?'<br><small>'+esc((o.shipments||[]).map(s=>s.tracking_number).join(' / '))+'</small>':'')+'</span><span>'+money(o)+'</span></button>').join('')||'<p class="help">没有匹配订单。'+(tracking?'订单快照中未记录的物流单号无法反查订单。':'')+'</p>';
  slot.querySelectorAll('[data-link]').forEach(b=>b.onclick=run(async()=>{await api('order-links',{customerId:d.customer.id,orderId:b.dataset.link,messageId});$('#dialog').close();await selectCustomer(d.customer.id,true);}));
  if(tracking&&!rows.length&&['postgresql','chatwoot'].includes(current?.source)){
   slot.insertAdjacentHTML('beforeend','<p class="help">确认这个物流单号属于当前订单后，可补充到本系统。不会修改店铺订单或自动填写发货时间。</p><button class="outline" id="supplement-tracking">补充到当前订单 '+esc(current.order_number)+'</button>');
   slot.querySelector('#supplement-tracking').onclick=run(async()=>{if(!/^[A-Za-z0-9][A-Za-z0-9-]{4,99}$/.test(term)){toast('请输入有效的物流单号（5–100 位字母、数字或连字符）');return;}await api('desk/order',{orderId:current.id,trackingNumber:term});$('#dialog').close();await selectCustomer(d.customer.id,true);});
  }
 }),250);}
 input.oninput=schedule;mode.onchange=()=>{$('#order-search-label').textContent=mode.value==='tracking'?'搜索物流单号':'搜索订单号或顾客邮箱';input.placeholder=mode.value==='tracking'?'输入物流单号…':'输入订单号或顾客邮箱…';schedule();};
}
window.addEventListener('beforeunload',e=>{if(state.dirty||state.sending){e.preventDefault();e.returnValue='';}});
async function init(){try{const b=await fetch(appBase+'/api/bootstrap').then(r=>r.json());state.token=b.token;const [,initialList]=await Promise.all([refreshMeta(),api('desk/conversations?filter=all')]);state.list=initialList;skeleton();setMobile('list');renderList();}catch(e){$('#app').innerHTML=`<div class="no-data"><h2>工作台暂时无法打开</h2><p>${esc(errorText(e))}</p><button id="retry-init" class="soft">重新连接</button></div>`;$('#retry-init').onclick=init;}}
const replySignatures=new Map();
const disabledSignatures=new Set();
function signatureRangeAfterEdit(previous,next,range){
 if(!range)return null;
 let start=0;while(start<previous.length&&start<next.length&&previous[start]===next[start])start++;
 let oldEnd=previous.length,newEnd=next.length;while(oldEnd>start&&newEnd>start&&previous[oldEnd-1]===next[newEnd-1]){oldEnd--;newEnd--;}
 if(oldEnd<=range.start)return {...range,start:range.start+newEnd-oldEnd};
 if(start>=range.start+range.text.length)return range;
 return null;
}
function signatureButton(){const button=$('#signature');if(!button)return;const active=replySignatures.has(state.id);button.setAttribute('aria-pressed',String(active));button.title=active?'禁用签名':'启用签名';button.setAttribute('aria-label',button.title);}
function restoreSignature(){
 const text=state.meta.signature?.text,range=replySignatures.get(state.id);
 if(range&&state.draft.slice(range.start,range.start+range.text.length)!==range.text)replySignatures.delete(state.id);
 if(!replySignatures.has(state.id)&&text&&state.draft.endsWith(text)){
  const start=state.draft.length-text.length;
  if(start===0||state.draft.slice(start-2,start)==='\n\n')replySignatures.set(state.id,{start:start?start-2:0,text:(start?'\n\n':'')+text});
 }
 signatureButton();
}
function enableDefaultSignature(){
 const area=$('#reply'),template=state.meta.signature?.text;
 if(!area||!template||disabledSignatures.has(state.id)||replySignatures.has(state.id))return;
 const start=area.value.length,text='\n\n'+template;
 area.value+=text;area.dispatchEvent(new Event('input'));
 replySignatures.set(state.id,{start,text});signatureButton();area.setSelectionRange(start,start);
}
function replyBody(){
 const range=replySignatures.get(state.id);
 return range&&state.draft.slice(range.start,range.start+range.text.length)===range.text?state.draft.slice(0,range.start)+state.draft.slice(range.start+range.text.length):state.draft;
}
async function toggleSignature(){
 if(state.sending)return;
 const id=state.id,area=$('#reply'),range=replySignatures.get(id);
 if(range){
  disabledSignatures.add(id);
  if(area.value.slice(range.start,range.start+range.text.length)===range.text)area.value=area.value.slice(0,range.start)+area.value.slice(range.start+range.text.length);
  replySignatures.delete(id);area.dispatchEvent(new Event('input'));signatureButton();area.focus();return;
 }
 await refreshMeta();if(state.id!==id||area!==$('#reply')||state.sending)return;
 const template=state.meta.signature?.text;
 if(!template)return toast('尚未绑定客服代号，请联系管理员在设置 → 客服签名中绑定。');
 disabledSignatures.delete(id);restoreSignature();if(replySignatures.has(id))return;
 const start=area.value.length,text=(start?'\n\n':'')+template;
 area.value+=text;area.dispatchEvent(new Event('input'));replySignatures.set(id,{start,text});signatureButton();area.focus();area.setSelectionRange(start,start);
}

let replyStatsSequence=0;
function openReplyStats(){
 const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),hour=new Date(Date.now()+8*3600000).getUTCHours();
 modal('客服回复统计',`<form id="reply-stats-filters" class="reply-stats-filters"><label>日期<input type="date" name="date" value="${today}" required></label><label>统计范围<select name="period"><option value="day">全天</option><option value="hour">按小时</option></select></label><label id="reply-stats-hour" hidden>小时<select name="hour">${Array.from({length:24},(_,i)=>`<option value="${i}" ${i===hour?'selected':''}>${String(i).padStart(2,'0')}:00–${String(i+1).padStart(2,'0')}:00</option>`).join('')}</select></label><button class="primary" type="submit">查询 / 刷新</button></form><p class="help">按北京时间（UTC+8）统计发送记录，仅计入邮件服务器已接收的回复，不代表最终送达。失败、结果未知和演示回复不计入。</p><div id="reply-stats-results" aria-live="polite"></div><p class="help">上线前未记录实际发送账号的邮件，单独列为“历史未归属”。</p>`);
 const dialog=$('#dialog');dialog.classList.add('reply-stats-dialog');dialog.addEventListener('close',()=>{replyStatsSequence++;dialog.classList.remove('reply-stats-dialog');},{once:true});
 const form=$('#reply-stats-filters');
 async function load(){
  const seq=++replyStatsSequence,slot=$('#reply-stats-results');slot.innerHTML='<p class="help">正在读取统计…</p>';
  try{const data=await api('desk/reply-stats?'+new URLSearchParams(new FormData(form)));if(seq!==replyStatsSequence||!slot.isConnected)return;
   slot.innerHTML=`<div class="reply-stats-summary"><span>${esc(data.date)} · ${data.period==='day'?'全天':String(data.hour).padStart(2,'0')+':00–'+String(data.hour+1).padStart(2,'0')+':00'}</span><strong>共 ${data.total} 封回复</strong></div><div class="reply-stats-table"><table><thead><tr><th scope="col">客服</th><th scope="col">代号</th><th scope="col">回复封数</th></tr></thead><tbody>${data.rows.map(row=>`<tr><td>${esc(row.name)}${row.active?'':'（已停用）'}</td><td>${esc(row.code||'未绑定')}</td><td>${row.count}</td></tr>`).join('')||'<tr><td colspan="3">暂无客服记录</td></tr>'}</tbody></table></div>${data.total===0?'<p class="help">所选时段暂无已被邮件服务器接收的回复。</p>':''}`;
  }catch(e){if(seq===replyStatsSequence&&slot.isConnected)slot.innerHTML=`<p class="help" role="alert">${esc(e.message==='INVALID_STATS_RANGE'?'请选择有效日期和小时。':errorText(e))}</p>`;}
 }
 form.onsubmit=e=>{e.preventDefault();load();};form.elements.period.onchange=()=>{$('#reply-stats-hour').hidden=form.elements.period.value!=='hour';load();};form.elements.date.onchange=load;form.elements.hour.onchange=load;load();
}

init();

function attachmentPreviewType(bytes){const hex=Array.from(bytes.slice(0,12),b=>b.toString(16).padStart(2,'0')).join('');if(hex.startsWith('89504e470d0a1a0a'))return'image/png';if(hex.startsWith('ffd8ff'))return'image/jpeg';if(hex.startsWith('474946383761')||hex.startsWith('474946383961'))return'image/gif';if(hex.startsWith('52494646')&&hex.slice(16,24)==='57454250')return'image/webp';if(hex.startsWith('255044462d'))return'application/pdf';return'';}
async function previewAttachment(button){
 const dialog=modal(button.dataset.filename,'<p id="attachment-preview-loading">正在加载附件…</p>');
 const marker=$('#attachment-preview-loading');
 const response=await fetch(appBase+(button.dataset.outgoing==='true'?'/api/desk/files/':'/api/attachments/')+button.dataset.attachment,{headers:{Authorization:'Bearer '+state.token}});
 if(!response.ok){if(marker.isConnected)marker.textContent='附件读取失败，请关闭后重试。';return;}
 const buffer=await response.arrayBuffer();if(!dialog.open||!marker.isConnected)return;
 const type=attachmentPreviewType(new Uint8Array(buffer)),url=URL.createObjectURL(new Blob([buffer],{type:type||'application/octet-stream'}));
 dialog.classList.add('attachment-preview-dialog');
 dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);dialog.classList.remove('attachment-preview-dialog');},{once:true});
 const container=marker.parentElement;container.replaceChildren();
 if(type.startsWith('image/')){const image=document.createElement('img');image.src=url;image.alt=button.dataset.filename;image.className='attachment-preview-image';container.append(image);}
 else if(type==='application/pdf'){const frame=document.createElement('iframe');frame.src=url;frame.title=button.dataset.filename;frame.className='attachment-preview-pdf';container.append(frame);}
 else{const text=document.createElement('p');text.textContent='此文件格式暂不支持浏览器预览，可以下载后查看。';container.append(text);}
 const link=document.createElement('a');link.href=url;link.download=button.dataset.filename;link.textContent='下载附件';link.className='attachment-preview-download';container.append(link);
}

function renderCustomerLabels(){const target=$('#customer-top-labels');if(!target||!state.detail)return;target.innerHTML=state.detail.labels.map(t=>`<span class="tag ${esc(t.color)}" ${labelStyle(t.color)}>${esc(t.name)}</span>`).join('');target.hidden=!state.detail.labels.length;}

function trackingCaptureView(order,number){const c=(order.trackingCaptures||[]).find(c=>c.number===number.toUpperCase());if(!c)return'';return`<div class="tracking-capture-result"><strong>AI 读取：${esc({delivered:'已签收',undelivered:'未签收',unknown:'状态未知'}[c.status]||'状态未知')}</strong><p>${esc(c.evidence)}</p><small>读取于 ${esc(fullTime(c.captured_at))} · 页面识别结果，非实时接口</small></div>`;}
